(* Structural gate over every ```ocaml block in the Univec SDK
 * docs (root README.md, ocaml/README.md, ocaml/REFERENCE.md). Generated by
 * @voxgig/sdkgen — do not edit by hand.
 *
 * Validates that each documented ocaml block is present, non-empty, and has
 * balanced delimiters. Missing docs are tolerated. See ReadmeExamplesTest_ocaml
 * for why this is a structural gate rather than a full compile harness. *)

open Testutil

let fence = "```ocaml"
let close_fence = "```"

let trim = String.trim

(* Read a whole file, or None when it is absent (a doc not generated). *)
let read_file (path : string) : string option =
  try Some (In_channel.with_open_text path In_channel.input_all)
  with Sys_error _ -> None

let split_lines (s : string) : string list = String.split_on_char '\n' s

(* Extract the body of every ```ocaml ... ``` fenced block from markdown.
 * Returns (blocks, unclosed) where unclosed is true when a fence was opened
 * but never closed before EOF — a malformed doc that must fail rather than
 * silently drop the unterminated block. *)
let extract_ocaml_blocks (md : string) : string list * bool =
  let blocks = ref [] in
  let cur = ref [] in
  let in_block = ref false in
  List.iter (fun line ->
      let t = trim line in
      if not !in_block then begin
        if t = fence then begin in_block := true; cur := [] end
      end
      else if t = close_fence then begin
        blocks := String.concat "\n" (List.rev !cur) :: !blocks;
        in_block := false
      end
      else cur := line :: !cur)
    (split_lines md);
  (List.rev !blocks, !in_block)

(* Balanced (), [], {} outside of string literals, with each closer matching
 * the most-recent opener (so "([)]" is rejected, not just counted). Naive
 * quote toggle: the generated snippets never embed an escaped quote inside a
 * string. *)
let is_balanced (block : string) : bool =
  let in_str = ref false in
  let stack = ref [] in
  let ok = ref true in
  String.iter (fun c ->
      if !ok then
        if c = '"' then in_str := not !in_str
        else if not !in_str then
          match c with
          | '(' -> stack := ')' :: !stack
          | '[' -> stack := ']' :: !stack
          | '{' -> stack := '}' :: !stack
          | ')' | ']' | '}' ->
            (match !stack with
             | top :: rest when top = c -> stack := rest
             | _ -> ok := false)
          | _ -> ())
    block;
  !ok && !stack = [] && not !in_str

let docs = [
  ("root README", "../README.md");
  ("ocaml/README", "README.md");
  ("ocaml/REFERENCE", "REFERENCE.md");
]

let () =
  test "readme.ocaml_snippets_wellformed" (fun () ->
      let total = ref 0 in
      List.iter (fun (label, path) ->
          match read_file path with
          | None -> ()   (* doc not generated in this run — tolerate *)
          | Some src ->
            let (blocks, unclosed) = extract_ocaml_blocks src in
            (* A fence opened but never closed is a malformed doc — fail
             * rather than silently skipping the unterminated block. *)
            check (label ^ " ocaml fence closed") (not unclosed);
            List.iteri (fun i block ->
                check (label ^ " block " ^ string_of_int (i + 1) ^ " non-empty")
                  (trim block <> "");
                check (label ^ " block " ^ string_of_int (i + 1) ^ " balanced delimiters")
                  (is_balanced block);
                incr total)
              blocks)
        docs;
      check "at least one ocaml code block across the docs" (!total > 0))
